template<typename T>
struct MyNumericLimits {
    static constexpr T epsilon() noexcept { return T(1.19209290e-7F); }  // For float, this is the actual epsilon value; compiler notes: Evaluated at compile-time if T is known.
    static constexpr T round_error() noexcept { return T(0.5); }  // Implementation note: Compiler may optimize this to a constant fold.
    static constexpr int min_exponent = -125;  // For float; stored as a compile-time constant, no runtime memory.
    // Other members follow similar patterns, ensuring all are constexpr for metaprogramming.
};
